using Astrea.BattleActions;
using LittleLeo.Variables;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ConfuseCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/ConfuseCustomDescription", order = 0)]
public class ConfuseCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private GameObjectReference actionDescriptionActionOwnerReference;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string text = "";
		text = ((!battleAction.TargetData) ? "AnyCP" : battleAction.TargetData.TargetCorruptPurifyID);
		string rawLocalizedDescription = GetRawLocalizedDescription(battleAction);
		ConfuseAction confuseAction = battleAction as ConfuseAction;
		bool playerConfuse = false;
		if (base.isOnBattleScene && actionDescriptionActionOwnerReference.value != null)
		{
			playerConfuse = confuseAction.IsPlayerConfuse(actionDescriptionActionOwnerReference.value);
		}
		int purifyChanceAmount = confuseAction.GetPurifyChanceAmount(playerConfuse, description: true);
		int num = 100 - purifyChanceAmount;
		rawLocalizedDescription = Smart.Format(rawLocalizedDescription, confuseAction.GetBrillianceModifierText(playerConfuse), num, (amountModified == "-2") ? ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedX() : amountModified);
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(text), rawLocalizedDescription);
	}
}
